import {escapeHtml as esc} from './agent-view.js';
import {LIVE_STATUSES} from './runtime-client.js';
import {ROLES} from './agents.js';
const time=v=>v?new Date(v).toLocaleString('zh-TW',{hour12:false}):'—';
const fraction=v=>v?`${v.passed} / ${v.total} · ${Math.round(v.score*100)}%`:'尚未評估';
const button=(attribute,label,disabled=false,kind='secondary')=>`<button class="button ${kind}" ${attribute} ${disabled?'disabled':''}>${label}</button>`;
const metric=(name,value,note)=>`<article class="metric"><div>${name}</div><strong class="runtime-metric">${esc(value)}</strong><small>${esc(note)}</small></article>`;

export function skillChart(candidates){
  const measured=candidates.filter(c=>c.validation);
  if(!measured.length)return '<div class="empty">驗證完成後顯示實測曲線；搜尋期間可先檢閱訓練結果。</div>';
  const x=i=>55+i*145,y=score=>175-score*135;
  return `<svg class="chart skill-chart" viewBox="0 0 700 220" role="img" aria-label="候選驗證成功率，來自固定十題的實際輸出比對">${[0,.5,1].map(v=>`<line x1="55" x2="650" y1="${y(v)}" y2="${y(v)}" stroke="#e7ebf2"/><text x="4" y="${y(v)+4}">${v*100}%</text>`).join('')}<polyline points="${measured.map((c,i)=>`${x(i)},${y(c.validation.score)}`).join(' ')}" fill="none" stroke="#5b5bd6" stroke-width="3"/>${measured.map((c,i)=>`<circle cx="${x(i)}" cy="${y(c.validation.score)}" r="4" fill="#5b5bd6"/><text x="${x(i)}" y="205" text-anchor="middle">${esc(c.id)}</text>`).join('')}</svg>`;
}

export function skillView(runtime){
  const workspace=runtime.data?.skills,run=runtime.selectedSkillRun||workspace?.latestRun,p=run?.skillProgress,result=run?.skillResult;
  const activeWork=runtime.data?.latestRun&&['queued','running'].includes(runtime.data.latestRun.status);
  const disabled=!!runtime.error||!workspace||runtime.actionBusy;
  const approved=workspace?.versions.some(v=>v.runId===run?.id);
  const eligible=!disabled&&run?.status==='completed'&&result?.eligible&&!approved&&workspace.activeVersionId===run.skillConfig.baseline.id;
  const selected=p?.candidates.find(c=>c.id===p.selectedId);
  const base=run?.skillConfig?.baseline?.skill||workspace?.active?.skill;
  const counts=p?.evaluations,searchCount=counts?counts.training+counts.validation+counts.heldout:0;
  return `<div class="page-heading"><div><p class="eyebrow">MEASURED SKILL EVOLUTION · LOCAL</p><h1>本機技能實驗</h1><p>從訓練回饋修改規則，檢閱實測結果與技能版本。</p></div><div class="actions">${button('data-live-refresh','↻ 立即更新')}${button('data-skill-start','▷ 開始技能演化',disabled||activeWork,'primary')}</div></div>
  <section class="card polling-bar"><div><strong>${runtime.error?'服務未連線／資料過期':workspace?'本機技能服務已連線':'等待技能服務'}</strong><p>最近成功更新：${time(runtime.lastSuccess)} · polling ${runtime.pollCount} 次 · ${runtime.enabled?'持續更新':'已暫停'}</p></div><label>候選上限<select data-skill-limit ${runtime.actionBusy?'disabled':''}>${[1,2,3,4].map(n=>`<option value="${n}" ${runtime.skillLimit===n?'selected':''}>${n} 個</option>`).join('')}</select></label>${button('data-live-toggle',runtime.enabled?'暫停 polling':'繼續 polling')}</section>
  ${runtime.error?`<div class="error-banner spaced">${esc(runtime.error)}。請啟動 WSL 的 <code>bash scripts/start-gui.sh</code>，使用本機網址操作；保留的資料已過期。</div>`:!workspace?'<div class="error-banner spaced">正在確認服務。若持續沒有資料，請更新專案並重新啟動本機服務至 v0.4.0。</div>':''}
  <div class="demo-banner spaced"><span class="info-icon">i</span><div><strong>本機規則搜尋 · 實測評估</strong><span>目標：<code>normalize-support-title</code>。固定四種文字規則，使用小型手寫資料集；結果僅適用於此任務。引擎為 local-rule-search-v1，不呼叫模型、nanobot 或 GEPA。</span></div></div>
  <div class="metrics">${metric('使用中的技能',workspace?.active?.label||'—',workspace?.activeVersionId||'服務尚未連線')}${metric('驗證結果',fraction(result?.selectedValidation||selected?.validation),'固定 validation 10 題 · 精確輸出比對')}${metric('保留測試',fraction(result?.heldout?.selected||p?.heldout?.selected),'選定候選後才評估 · 20 題')}${metric('實際任務評估',searchCount,'包含所有訓練探測、驗證與保留測試')}</div>
  <section class="card"><div class="card-heading"><div><h2>${run?`實驗 ${esc(run.id)}`:'開始第一輪演化'}</h2><p>${run?`${esc(LIVE_STATUSES[run.status])} · 基準 ${esc(run.skillConfig.baseline.label)} · 候選上限 ${run.skillConfig.maxCandidates}`:'使用目前啟用的五個角色，由本機程序依序執行。'}</p></div>${run&&['queued','running'].includes(run.status)?button(`data-live-cancel="${esc(run.id)}"`,'取消執行',disabled,'danger'):''}</div>
  ${run?`<div class="skill-role-strip">${run.agents.map(a=>`<div><strong>${ROLES[a.role]||esc(a.role)}</strong><span class="live-status ${runtime.error?'stale':esc(a.status)}">${runtime.error?'狀態過期':LIVE_STATUSES[a.status]}</span><small>${esc(a.name)} · PID ${a.pid??'—'}</small></div>`).join('')}</div><p class="body-copy">${esc(run.agents.find(a=>a.status==='running')?.task||result?.decision||'等待角色執行')} · 檢閱驗證另執行 ${counts?.verification||0} 題；不計入上方搜尋評估次數。<a href="#runtime">查看行程與輸出 ↗</a></p>${skillChart(p?.candidates||[])}<div class="table-wrap"><table><thead><tr><th>候選</th><th>新增規則</th><th>訓練</th><th>驗證</th><th>Skill hash</th></tr></thead><tbody>${(p?.candidates||[]).map(c=>`<tr><td>${esc(c.id)}${c.id===p.selectedId?' · 選定':''}</td><td>${esc(c.mutation||'凍結基準')}</td><td>${fraction(c.training)}</td><td>${fraction(c.validation)}</td><td><code title="${esc(c.skill.hash)}">${esc(c.skill.hash.slice(0,12))}</code></td></tr>`).join('')||'<tr><td colspan="5">等待候選資料</td></tr>'}</tbody></table></div>`:'<div class="empty">按「開始技能演化」建立實際工作。技能名稱、描述、執行順序及資料分割保持固定，只搜尋四種 allowlisted 規則。</div>'}</section>
  <section class="card spaced"><div class="card-heading"><div><h2>技能變更與人工檢閱</h2><p>候選須通過驗證改善與保留測試檢查；核准後建立本機版本。</p></div>${button(`data-skill-approve="${esc(run?.id||'')}"`,approved?'已建立版本':'核准並啟用候選',!eligible,'primary')}</div><div class="diff"><div><div class="diff-heading">基準 · ${esc(run?.skillConfig.baseline.label||workspace?.active.label||'—')}</div><pre>${esc(base?.body||'等待本機技能資料')}</pre></div><div><div class="diff-heading accent">選定候選 · ${esc(p?.selectedId||'尚未選定')}</div><pre class="candidate-code">${esc(result?.selectedSkill.body||selected?.skill.body||'完成訓練與驗證後顯示選定技能。')}</pre></div></div><div class="card-bottom"><span>${runtime.error?'快照過期，核准操作已停用。':approved?'此實驗已有不可變版本，可在下方切換。':result?.eligible?(workspace?.activeVersionId===run.skillConfig.baseline.id?'已通過可信重算，等待人工核准。':'基準版本已變更，請重新建立實驗。'):run?.status==='completed'?'沒有符合發布條件的改善，保留基準。':'尚未完成全部評估，核准操作已停用。'}</span><span>僅啟用本機規則技能；後續實驗使用新版本。</span></div></section>
  <section class="card spaced"><div class="card-heading"><div><h2>版本與回復</h2><p>SQLite 保存版本與來源證據；切換不影響執行中工作已凍結的技能。</p></div><span class="soft-tag">revision ${workspace?.revision||'—'}</span></div>${(workspace?.versions||[]).map(v=>`<div class="release-row"><span class="version-icon">◇</span><div><h3>${esc(v.label)} · ${esc(v.skill.name)}</h3><p>${esc(v.skill.hash.slice(0,12))} · ${v.runId?esc(v.runId):'初始基準'} · ${time(v.createdAt)}</p></div>${button(`data-skill-export="${esc(v.id)}"`,'↓ SKILL.md',disabled)}${button(`data-skill-activate="${esc(v.id)}"`,v.id===workspace.activeVersionId?'使用中':'切換至此版本',disabled||v.id===workspace.activeVersionId)}</div>`).join('')||'<div class="empty">等待本機版本資料</div>'}<p class="body-copy">匯出的 Markdown 可供後續 adapter 使用；本階段的執行語意由同版本 JSON policy 決定。未安裝到外部代理人。</p></section>
  <section class="card spaced"><div class="card-heading"><div><h2>試跑使用中的技能</h2><p>在本機套用目前啟用版本，切換或回復後可比較實際輸出。</p></div></div><form id="skill-trial-form" class="skill-trial-form"><label>輸入文字（最多 500 字元）<input name="text" data-skill-input maxlength="500" value="${esc(runtime.trialInput??'  Ｓｅｒｖｉｃｅ   Down  ')}"></label><button type="submit" class="button secondary" ${disabled?'disabled':''}>執行技能試跑</button></form>${runtime.skillTrial?`<div class="skill-trial-result"><p>${esc(runtime.skillTrial.label)} · ${esc(runtime.skillTrial.versionId)}${runtime.skillTrial.versionId!==workspace?.activeVersionId?' · 此次結果來自先前啟用版本':''}</p><pre>${esc(JSON.stringify(runtime.skillTrial.output))}</pre><small>Skill hash：${esc(runtime.skillTrial.skillHash)}</small></div>`:''}</section>
  ${p?.trainingFailures?.length?`<section class="card spaced"><div class="card-heading"><div><h2>基準訓練失敗案例</h2><p>實際輸出比對，最多顯示 8 題；完整 trace 保存在執行產物。</p></div></div><div class="table-wrap"><table><thead><tr><th>Task</th><th>輸入</th><th>實際輸出</th><th>預期輸出</th></tr></thead><tbody>${p.trainingFailures.map(r=>`<tr><td>${esc(r.taskId)}</td><td><code>${esc(JSON.stringify(r.input))}</code></td><td><code>${esc(JSON.stringify(r.output))}</code></td><td><code>${esc(JSON.stringify(r.expected))}</code></td></tr>`).join('')}</tbody></table></div></section>`:''}
  ${run?`<section class="card spaced"><div class="card-heading"><div><h2>執行產物與重現資訊</h2><p>資料集：${esc(run.skillConfig.provenance.datasetRevision)} · 引擎 local-rule-search-v1</p></div></div><dl class="agent-properties"><dt>Dataset hash</dt><dd><code>${esc(run.skillConfig.provenance.datasetHash)}</code></dd><dt>Evaluator hash</dt><dd><code>${esc(run.skillConfig.provenance.evaluatorHash)}</code></dd><dt>分割</dt><dd>Train 20 / Validation 10 / Held-out 20</dd></dl><div class="artifact-links">${run.artifacts.map(name=>`<a href="/api/v1/runtime/runs/${encodeURIComponent(run.id)}/artifacts/${encodeURIComponent(name)}" target="_blank" rel="noreferrer">${esc(name)} ↗</a>`).join('')||'<span class="muted">工作結束後列出產物</span>'}</div></section>`:''}
  <section class="card spaced"><div class="card-heading"><div><h2>近期技能實驗</h2><p>選取舊實驗可檢閱詳細證據。</p></div>${button('data-skill-select=""','查看最新實驗')}</div><div class="table-wrap"><table><thead><tr><th>實驗</th><th>狀態</th><th>檢閱結果</th><th>建立時間</th></tr></thead><tbody>${(workspace?.runs||[]).map(r=>`<tr><td><button class="text-button" data-skill-select="${esc(r.id)}">${esc(r.id)}</button></td><td>${esc(LIVE_STATUSES[r.status])}</td><td>${r.eligible===true?'候選可檢閱':r.eligible===false?'保留基準':'等待評估'}</td><td>${time(r.createdAt)}</td></tr>`).join('')||'<tr><td colspan="4">尚無技能實驗</td></tr>'}</tbody></table></div></section>`;
}

export function skillMarkdown(version){
  const value=version.skill;
  return `---\nname: ${value.name}\ndescription: ${value.description}\n---\n\n# Instructions\n\n${value.body}`;
}
